package com.wenwen.ai.export;
import com.wenwen.mapper.*;
import java.io.*;
import java.util.*;
import org.springframework.stereotype.Component;
import org.springframework.transaction.*;
import org.springframework.transaction.support.TransactionTemplate;

/** 两表原子创建；网络永远在短事务退出之后。 */
@Component public final class ExportApplicationStore {
    private final AiExportApplicationMapper mapper;private final ExportMapper legacy;private final TransactionTemplate write,read;
    public ExportApplicationStore(AiExportApplicationMapper mapper,ExportMapper legacy,PlatformTransactionManager manager){this.mapper=mapper;this.legacy=legacy;write=new TransactionTemplate(manager);write.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);read=new TransactionTemplate(manager);read.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);read.setReadOnly(true);}
    public ExportApplicationRecord find(long owner,String requestId){Map<String,Object> q=event(owner,0);q.put("requestId",requestId);return read.execute(s->validate(mapper.find(q)));}
    public ExportApplicationRecord byId(long owner,long id){return read.execute(s->validate(mapper.find(event(owner,id))));}
    public ExportApplicationRecord create(long owner,ExportApplicationQuery q,String summary,long now)throws IOException {
        Map<String,Object> r=event(owner,0);r.put("requestId",q.requestId);r.put("requestHash",q.hash);r.put("source",q.export.source);r.put("referenceId",q.export.referenceId);r.put("purposeCode",q.purposeCode);r.put("summary",summary);r.put("createdAt",now);
        Map<String,Object> a=new LinkedHashMap<>();a.put("doctorId",owner);a.put("doctorName",null);a.put("startDate",q.startDate);a.put("endDate",q.endDate);a.put("scope",ExportApplicationSummary.scope(summary));a.put("reason",q.reason);a.put("mailTo",null);
        return write.execute(s->{one(mapper.reserve(r));one(legacy.insertApplication(a));Object id=a.get("id");if(!(id instanceof Number)||((Number)id).longValue()<1)throw bad();r.put("applicationId",((Number)id).longValue());one(mapper.attach(r));return validate(mapper.find(r));});
    }
    public ExportApplicationRecord claim(long owner,long id,long now,String to,String from){return write.execute(s->{Map<String,Object> e=event(owner,id);e.put("lock",true);ExportApplicationRecord r=validate(mapper.find(e));if(r==null)throw new com.wenwen.ai.query.CohortException(404,"RESOURCE_NOT_FOUND","申请不存在");if(!Arrays.asList("PENDING","FAILED").contains(r.text("mailState")))return null;long no=r.number("attemptNo");if(no>=Integer.MAX_VALUE)throw bad();e.put("oldState",r.text("mailState"));e.put("attemptNo",no);e.put("nextAttemptNo",no+1);e.put("attemptId",UUID.randomUUID().toString());e.put("now",now);e.put("mailFrom",r.text("mailFrom")!=null?r.text("mailFrom"):from);if(to!=null&&r.text("mailTo")==null){e.put("mailTo",to);one(mapper.bindRecipient(e));}one(mapper.claim(e));return validate(mapper.find(e));});}
    public ExportApplicationRecord settle(ExportApplicationRecord r,String state,String reason,long now){return write.execute(s->{Map<String,Object> e=event(r.number("owner"),r.number("applicationId"));e.put("attemptId",r.text("attemptId"));e.put("attemptNo",r.number("attemptNo"));e.put("newState",state);e.put("lastError",reason);e.put("now",now);if("SENT".equals(state))one(mapper.accepted(e));one(mapper.settle(e));return validate(mapper.find(e));});}
    public static ExportApplicationRecord validate(ExportApplicationRecord r){if(r==null)return null;try{if(r.number("owner")<1||r.number("applicationId")<1||r.number("applicationId")!=r.number("legacyId")||r.number("owner")!=r.number("legacyOwner")||!com.wenwen.ai.result.AnalysisCursor.canonicalId(r.text("requestId"))||!r.text("requestHash").matches("[0-9a-f]{64}"))throw bad();ExportApplicationQuery.date(r.text("startDate"));ExportApplicationQuery.date(r.text("endDate"));if(r.text("startDate").compareTo(r.text("endDate"))>0||r.text("reason")==null||r.text("reason").codePointCount(0,r.text("reason").length())<1||r.text("reason").codePointCount(0,r.text("reason").length())>1000)throw bad();com.fasterxml.jackson.databind.JsonNode n=ExportApplicationSummary.read(r.text("summary"));if(!n.path("source").asText().equals(r.text("source"))||!n.path("referenceId").asText().equals(r.text("referenceId"))||!Arrays.asList("RESEARCH","DATA_CHECK","OTHER").contains(r.text("purposeCode")))throw bad();String state=r.text("mailState");if(!Arrays.asList("PENDING","UNKNOWN","FAILED","SENT").contains(state))throw bad();long no=r.number("attemptNo");if(no<0||no>Integer.MAX_VALUE||("PENDING".equals(state)?no!=0||r.text("attemptId")!=null:no==0||!com.wenwen.ai.result.AnalysisCursor.canonicalId(r.text("attemptId"))))throw bad();if(r.number("mailSent")!=("SENT".equals(state)?1:0))throw bad();r.number("createdAt");
        String error=r.text("lastError");if(error!=null&&!Arrays.asList("NOT_CONFIGURED","INVALID_MAIL_CONFIG","RECIPIENT_CHANGED","NOTIFICATION_BUSY","PRE_DATA_REJECTED","PRE_DATA_IO_FAILED","DATA_OUTCOME_UNKNOWN","DEADLINE","CALLER_INTERRUPTED","SERVICE_STOPPED","STATE_UPDATE_UNCONFIRMED","IN_PROGRESS_OR_UNCERTAIN").contains(error))throw bad();
        if("PENDING".equals(state)){if(error!=null||r.get("attemptStartedAt")!=null||r.get("decidedAt")!=null)throw bad();}else {r.number("attemptStartedAt");if("SENT".equals(state)){if(error!=null)throw bad();r.number("decidedAt");}else if(error==null)throw bad();if("FAILED".equals(state))r.number("decidedAt");if(r.get("decidedAt")!=null)r.number("decidedAt");}
        if((r.text("mailTo")==null)!=(r.text("mailFrom")==null))throw bad();if(r.text("mailTo")!=null){try{com.wenwen.ai.export.mail.ExportNotificationSettings.address(r.text("mailTo"));com.wenwen.ai.export.mail.ExportNotificationSettings.address(r.text("mailFrom"));}catch(javax.mail.internet.AddressException e){throw bad();}}else if("SENT".equals(state))throw bad();
        String reason=r.text("reason");if(!reason.equals(reason.trim()))throw bad();for(int i=0;i<reason.length();i++){char ch=reason.charAt(i);if(Character.isHighSurrogate(ch)){if(++i>=reason.length()||!Character.isLowSurrogate(reason.charAt(i)))throw bad();}else if(Character.isLowSurrogate(ch))throw bad();}return r;}catch(IOException|RuntimeException e){throw bad();}}
    private static Map<String,Object> event(long owner,long id){Map<String,Object> e=new LinkedHashMap<>();e.put("owner",owner);if(id>0)e.put("applicationId",id);return e;}
    private static void one(int n){if(n!=1)throw bad();}
    private static IllegalStateException bad(){return new IllegalStateException("申请记录损坏或写入未确认");}
}
